  "anomalies": [
    {
      "category": "bridged_nets",
      "components": ["M2A", "U9"],
      "pins": ["M2A.IO11", "U9.16", "U9.21"],
      "nets": ["NET0041", "NET0079"],
      "observed": "On the SoC sheet, ESP32-C6 pin IO11 is labeled NET0041. On the peristaltic pump drivers sheet, NET0041 is connected to U9 pin 21 (OA2, a motor-coil output), while U9 pin 16 (STEP) is labeled NET0079 and has no visible connection to the ESP32.",
      "expected": "The specification states that the pH-down dosing pump STEP line is on ESP32 IO11 and that each TMC2209 has an individual STEP line; IO11 should drive the STEP pin, not a motor-coil output.",
      "evidence": [
        {
          "source": "spec",
          "quote": "STEP_PH_DN | IO11 | GPIO21 | \"Pump pH Down\" switch (comment: \"Moved from GPIO8\")"
        },
        {
          "source": "spec",
          "quote": "each drives a 2-phase coil output (/A_xx+/-, /B_xx+/-) to connectors H7/H8/H9 ... plus individual STEP lines"
        },
        {
          "source": "schematic",
          "quote": "SoC sheet: IO11 J2 NET0041; Peristaltic Pump Drivers sheet: U9 pin 16 STEP = NET0079, U9 pin 21 OA2 = NET0041"
        }
      ],
      "impact": "The pH-down pump STEP input is floating and the ESP32 GPIO is tied to a motor coil output, so the pump cannot be commanded as intended and the MCU pin may be driven by coil voltage/current.",
      "confidence": 0.78
    }
  ],
  "summary": "The schematic contains a connectivity error on the pH-down stepper driver: ESP32 IO11 is tied to the U9 OA2 motor-coil net NET0041, while the U9 STEP net NET0079 is not connected to the MCU, contrary to the intended individual STEP_PH_DN line on IO11."
}

